panels.program:
root = Card([header, summary, table, callout], sources)

header = CardHeader("NVIDIA FY2026 Revenue Increase Analysis", "NVIDIA 10-K, Fiscal Year Ended January 25, 2026")

summary = TextContent(
  "NVIDIA's revenue increased significantly in fiscal year 2026 compared to fiscal year 2025, mainly driven by growth in accelerated computing and AI platforms. The Compute & Networking segment revenue rose 67% year-over-year, with Data Center computing growing 59% fueled by demand for the Blackwell computing platform and Data Center networking revenue growing 142% due to the introduction and ramp-up of NVLink compute fabric and growth in Ethernet and InfiniBand platforms. The Graphics segment also saw a 57% revenue increase, driven by sales of GPUs built on the Blackwell architecture. These factors collectively contributed to a 65% total revenue increase to $215.9 billion in FY2026. Operating income increased in both major segments despite a notable $4.5 billion charge related to inventory and purchase obligations early in FY2026. This reflects strong demand and strategic investment in new AI and computing hardware.",
  "default"
)

table = Table([
  Col("Segment", ["Compute & Networking", "Graphics", "Total"]),
  Col("Revenue FY2026", ["$193.5 billion", "$22.5 billion", "$215.9 billion"]),
  Col("Revenue FY2025", ["$116.2 billion", "$14.3 billion", "$130.5 billion"]),
  Col("Year-over-Year Change", ["67%", "57%", "65%"])
])

callout = Callout("info",
  "Revenue Growth Drivers",
  "The primary drivers for NVIDIA's FY2026 revenue growth were the accelerated computing and AI platform shifts, particularly with Data Center demand for Blackwell and networking platforms, and increased Graphics sales with Blackwell GPUs."
)

